{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); ex=['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for v in ex:
 d=x.dropna(subset=[v,'recovery_score','hospital']); m=smf.ols(f'recovery_score ~ {v} + C(hospital)',d).fit()
 print(v, len(d), round(m.params[v],4), round(m.pvalues[v],5), round(m.rsquared,3))"}
